def solve_knights_tour():
    N = 64
    SIZE = 8

    # Fixed assignments: x[step] = cell
    fixed = {
        2: 27, 3: 21, 10: 16, 11: 1, 19: 24, 21: 3,
        27: 51, 38: 38, 50: 43, 51: 60, 59: 53, 61: 42
    }

    def get_moves(cell):
        r, c = cell // 8, cell % 8
        moves = []
        for dr, dc in [(-2,-1),(-2,1),(-1,-2),(-1,2),(1,-2),(1,2),(2,-1),(2,1)]:
            nr, nc = r+dr, c+dc
            if 0 <= nr < 8 and 0 <= nc < 8:
                moves.append(nr*8+nc)
        return moves

    # Precompute moves
    knight_moves = [get_moves(i) for i in range(64)]

    # Check fixed assignments are consistent (each consecutive pair must be knight moves)
    fixed_steps = sorted(fixed.keys())
    for i in range(len(fixed_steps)-1):
        s1, s2 = fixed_steps[i], fixed_steps[i+1]
        if s2 == s1 + 1:
            c1, c2 = fixed[s1], fixed[s2]
            if c2 not in knight_moves[c1]:
                print(f"Inconsistent: step {s1}={c1} -> step {s2}={c2} not a valid knight move")
                return None

    # Backtracking with Warnsdorff's heuristic
    path = [None] * 64
    visited = [False] * 64

    # Set fixed values
    path[0] = 0
    visited[0] = True

    def warnsdorff_score(cell, visited):
        return sum(1 for m in knight_moves[cell] if not visited[m])

    def backtrack(step):
        if step == 64:
            return True

        # If this step is fixed
        if step in fixed:
            cell = fixed[step]
            if visited[cell]:
                return False
            # Check previous step connects
            if step > 0 and path[step-1] is not None:
                if cell not in knight_moves[path[step-1]]:
                    return False
            path[step] = cell
            visited[cell] = True
            if backtrack(step + 1):
                return True
            visited[cell] = False
            path[step] = None
            return False
        else:
            # Get candidates from previous cell
            prev_cell = path[step-1]
            if prev_cell is None:
                return False

            candidates = [m for m in knight_moves[prev_cell] if not visited[m]]

            # Check if next fixed step constrains us
            # Find next fixed step
            next_fixed_step = None
            for fs in sorted(fixed.keys()):
                if fs > step:
                    next_fixed_step = fs
                    break

            # Filter: if next_fixed_step == step+1, candidate must connect to fixed cell
            if next_fixed_step == step + 1:
                next_fixed_cell = fixed[next_fixed_step]
                candidates = [c for c in candidates if next_fixed_cell in knight_moves[c] or next_fixed_step == step+1 and c == next_fixed_cell]
                # Actually: candidate at step must have next_fixed_cell as a knight move
                candidates = [c for c in candidates if next_fixed_cell in knight_moves[c]]

            # Sort by Warnsdorff's heuristic
            candidates.sort(key=lambda c: warnsdorff_score(c, visited))

            for cell in candidates:
                path[step] = cell
                visited[cell] = True
                if backtrack(step + 1):
                    return True
                visited[cell] = False
                path[step] = None

            return False

    if backtrack(1):
        return path
    return None

