from collections import defaultdict, deque

def has_triangle(edges, n):
    """Check if graph has any triangle (3-cycle)."""
    adj = defaultdict(set)
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)
    for u in range(n):
        for v in adj[u]:
            for w in adj[v]:
                if w != u and w in adj[u]:
                    return True
    return False

def girth(edges, n):
    """Compute girth of graph."""
    adj = defaultdict(set)
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    min_cycle = float('inf')
    for start in range(n):
        # BFS from start
        dist = {start: 0}
        parent = {start: -1}
        queue = deque([start])
        while queue:
            node = queue.popleft()
            for nb in adj[node]:
                if nb not in dist:
                    dist[nb] = dist[node] + 1
                    parent[nb] = node
                    queue.append(nb)
                elif parent[node] != nb:
                    # Found a cycle
                    cycle_len = dist[node] + dist[nb] + 1
                    min_cycle = min(min_cycle, cycle_len)
    return min_cycle

def greedy_color(edges, n):
    """Greedy graph coloring, returns number of colors used."""
    adj = defaultdict(set)
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    colors = {}
    for node in range(n):
        neighbor_colors = {colors[nb] for nb in adj[node] if nb in colors}
        for c in range(n):
            if c not in neighbor_colors:
                colors[node] = c
                break
    return max(colors.values()) + 1 if colors else 0

