        if idx == len(nodes):
            return True
        v = nodes[idx]
        neighbor_colors = {color[u] for u in G.neighbors(v) if u in color}
        for c in range(3):
            if c not in neighbor_colors:
                color[v] = c
                if backtrack(idx + 1):
                    return True
                del color[v]
        return False

    return backtrack(0)

