from collections import deque

def try_2color(adj, n):
    color = [-1] * n
    for start in range(n):
        if color[start] != -1:
            continue
        if start not in adj and start not in [v for u,vs in adj.items() for v in vs]:
            continue
        queue = deque([start])
        color[start] = 0
        while queue:
            node = queue.popleft()
            for nb in adj[node]:
                if color[nb] == -1:
                    color[nb] = 1 - color[node]
                    queue.append(nb)
                elif color[nb] == color[node]:
                    return None  # Not bipartite
    return color

