    grid[7] = 2
    grid[9] = 1
    grid[12] = 4

    def get_row(i): return i // 4
    def get_col(i): return i % 4
    def get_block(i): return (i // 4 // 2) * 2 + (i % 4 // 2)

    def is_valid(grid, pos, val):
        r, c, b = get_row(pos), get_col(pos), get_block(pos)
        for i in range(16):
            if i == pos:
                continue
            if grid[i] == 0:
                continue
            if get_row(i) == r and grid[i] == val:
                return False
            if get_col(i) == c and grid[i] == val:
                return False
            if get_block(i) == b and grid[i] == val:
                return False
        return True

    def backtrack(pos):
        if pos == 16:
            return True
        if grid[pos] != 0:
            return backtrack(pos + 1)
        for val in range(1, 5):
            if is_valid(grid, pos, val):
                grid[pos] = val
                if backtrack(pos + 1):
                    return True
                grid[pos] = 0
        return False

    if backtrack(0):
        return grid
    return None

